//! Test-only reduction blocking: preserve full-K production as a paired control.
use super::*;
use crate::runtime::nhwc::pointwise::tests::{assert_bits, oracle, values};
use std::time::{Duration, Instant};

/// Keep each coefficient block hot while all eight spatial tiles consume it.
/// Partials retain the original ascending-K chains; only final stores apply
/// residuals/activations. The bounded partial array occupies 3,072 stack bytes.
#[target_feature(enable = "neon")]
#[allow(clippy::too_many_arguments)]
unsafe fn execute_blocked<const KC: usize>(
    input: &[f32],
    bias: &[f32],
    packed: &PackedMatrix,
    output: &mut [f32],
    first: usize,
    inner: usize,
    columns: usize,
    store: &impl StoreTransform,
) {
    assert!(KC == 256 || KC == 512);
    assert!(inner > 0 && columns > 0);
    assert!(packed.matches(inner, columns));
    assert_eq!(output.len() % columns, 0);
    assert!(bias.is_empty() || bias.len() == columns);
    let rows = output.len() / columns;
    assert_eq!(input.len(), rows * inner);
    for group in (0..rows).step_by(GROUP_ROWS) {
        let count = (rows - group).min(GROUP_ROWS);
        let input = &input[group * inner..(group + count) * inner];
        for (block, panel) in packed.data().chunks_exact(inner * 16).enumerate() {
            let column = block * 16;
            let seed = std::array::from_fn(|v| initial::<4>(bias, column + v * 4));
            let mut partial = [seed; GROUP_ROWS];
            for k0 in (0..inner).step_by(KC) {
                let end = (k0 + KC).min(inner);
                let panel = &panel[k0 * 16..end * 16];
                for tile in (0..count).step_by(ROWS) {
                    let rows = std::array::from_fn(|r| {
                        let start = (tile + r).min(count - 1) * inner;
                        &input[start + k0..start + end]
                    });
                    let seeds: &[[Simd<f32, 4>; 4]; ROWS] = partial[tile..tile + ROWS]
                        .try_into()
                        .expect("complete partial tile");
                    // SAFETY: every row and panel covers exactly end-k0 values;
                    // partial seeds continue those rows' preceding FMA chains.
                    let sums = unsafe { seeded_tile(rows, panel, seeds) };
                    partial[tile..tile + ROWS].copy_from_slice(&sums);
                }
            }
            for (r, sums) in partial[..count].iter().enumerate() {
                for (v, &sum) in sums.iter().enumerate() {
                    store_row(
                        sum,
                        output,
                        group + r,
                        column + v * 4,
                        columns,
                        first,
                        store,
                    );
                }
            }
        }
    }
}

/// Identical lane-FMA order and register shape to the production six-row leaf,
/// with independent seeds rather than broadcasting one bias row to all six.
#[target_feature(enable = "neon")]
#[inline(never)]
unsafe fn seeded_tile(
    rows: [&[f32]; ROWS],
    panel: &[f32],
    seeds: &[[Simd<f32, 4>; 4]; ROWS],
) -> [[Simd<f32, 4>; 4]; ROWS] {
    assert_eq!(panel.len() % 16, 0);
    let inner = panel.len() / 16;
    assert!(rows.iter().all(|row| row.len() == inner));
    macro_rules! initialize {
        ($r:literal, $a:ident, $b:ident, $c:ident, $d:ident) => {
            let (mut $a, mut $b, mut $c, mut $d) = (
                native(seeds[$r][0]),
                native(seeds[$r][1]),
                native(seeds[$r][2]),
                native(seeds[$r][3]),
            );
        };
    }
    initialize!(0, a00, a01, a02, a03);
    initialize!(1, a10, a11, a12, a13);
    initialize!(2, a20, a21, a22, a23);
    initialize!(3, a30, a31, a32, a33);
    initialize!(4, a40, a41, a42, a43);
    initialize!(5, a50, a51, a52, a53);
    for block in 0..inner / 4 {
        let k = block * 4;
        // SAFETY: the checked rows contain all four lanes at this K block.
        let [v0, v1, v2, v3, v4, v5] = rows.map(|row| unsafe { vld1q_f32(row.as_ptr().add(k)) });
        macro_rules! lane {
            ($lane:literal) => {{
                // SAFETY: each packed K row contains all sixteen columns.
                let w0 = unsafe { vld1q_f32(panel.as_ptr().add((k + $lane) * 16)) };
                let w1 = unsafe { vld1q_f32(panel.as_ptr().add((k + $lane) * 16 + 4)) };
                a00 = vfmaq_laneq_f32::<$lane>(a00, w0, v0);
                a01 = vfmaq_laneq_f32::<$lane>(a01, w1, v0);
                a10 = vfmaq_laneq_f32::<$lane>(a10, w0, v1);
                a11 = vfmaq_laneq_f32::<$lane>(a11, w1, v1);
                a20 = vfmaq_laneq_f32::<$lane>(a20, w0, v2);
                a21 = vfmaq_laneq_f32::<$lane>(a21, w1, v2);
                a30 = vfmaq_laneq_f32::<$lane>(a30, w0, v3);
                a31 = vfmaq_laneq_f32::<$lane>(a31, w1, v3);
                a40 = vfmaq_laneq_f32::<$lane>(a40, w0, v4);
                a41 = vfmaq_laneq_f32::<$lane>(a41, w1, v4);
                a50 = vfmaq_laneq_f32::<$lane>(a50, w0, v5);
                a51 = vfmaq_laneq_f32::<$lane>(a51, w1, v5);
                let w2 = unsafe { vld1q_f32(panel.as_ptr().add((k + $lane) * 16 + 8)) };
                let w3 = unsafe { vld1q_f32(panel.as_ptr().add((k + $lane) * 16 + 12)) };
                a02 = vfmaq_laneq_f32::<$lane>(a02, w2, v0);
                a03 = vfmaq_laneq_f32::<$lane>(a03, w3, v0);
                a12 = vfmaq_laneq_f32::<$lane>(a12, w2, v1);
                a13 = vfmaq_laneq_f32::<$lane>(a13, w3, v1);
                a22 = vfmaq_laneq_f32::<$lane>(a22, w2, v2);
                a23 = vfmaq_laneq_f32::<$lane>(a23, w3, v2);
                a32 = vfmaq_laneq_f32::<$lane>(a32, w2, v3);
                a33 = vfmaq_laneq_f32::<$lane>(a33, w3, v3);
                a42 = vfmaq_laneq_f32::<$lane>(a42, w2, v4);
                a43 = vfmaq_laneq_f32::<$lane>(a43, w3, v4);
                a52 = vfmaq_laneq_f32::<$lane>(a52, w2, v5);
                a53 = vfmaq_laneq_f32::<$lane>(a53, w3, v5);
            }};
        }
        lane!(0);
        lane!(1);
        lane!(2);
        lane!(3);
    }
    for k in inner / 4 * 4..inner {
        // SAFETY: the final partial input block still has a complete panel row.
        let w0 = unsafe { vld1q_f32(panel.as_ptr().add(k * 16)) };
        let w1 = unsafe { vld1q_f32(panel.as_ptr().add(k * 16 + 4)) };
        let w2 = unsafe { vld1q_f32(panel.as_ptr().add(k * 16 + 8)) };
        let w3 = unsafe { vld1q_f32(panel.as_ptr().add(k * 16 + 12)) };
        macro_rules! tail_row {
            ($r:literal, $a:ident, $b:ident, $c:ident, $d:ident) => {{
                let value = rows[$r][k];
                $a = vfmaq_n_f32($a, w0, value);
                $b = vfmaq_n_f32($b, w1, value);
                $c = vfmaq_n_f32($c, w2, value);
                $d = vfmaq_n_f32($d, w3, value);
            }};
        }
        tail_row!(0, a00, a01, a02, a03);
        tail_row!(1, a10, a11, a12, a13);
        tail_row!(2, a20, a21, a22, a23);
        tail_row!(3, a30, a31, a32, a33);
        tail_row!(4, a40, a41, a42, a43);
        tail_row!(5, a50, a51, a52, a53);
    }
    [
        [portable(a00), portable(a01), portable(a02), portable(a03)],
        [portable(a10), portable(a11), portable(a12), portable(a13)],
        [portable(a20), portable(a21), portable(a22), portable(a23)],
        [portable(a30), portable(a31), portable(a32), portable(a33)],
        [portable(a40), portable(a41), portable(a42), portable(a43)],
        [portable(a50), portable(a51), portable(a52), portable(a53)],
    ]
}

struct ResidualReluStore;
impl StoreTransform for ResidualReluStore {
    fn scalar(&self, value: f32, index: usize) -> f32 {
        (value + (index % 17) as f32 / 31. - 0.25).max(0.)
    }
    fn vector<const LANES: usize>(
        &self,
        value: Simd<f32, LANES>,
        index: usize,
    ) -> Simd<f32, LANES> {
        use std::simd::num::SimdFloat;
        (value
            + Simd::from_array(std::array::from_fn(|lane| {
                ((index + lane) % 17) as f32 / 31.
            }))
            - Simd::splat(0.25))
        .simd_max(Simd::splat(0.))
    }
}

#[test]
fn blocked_pointwise_preserves_fma_boundaries_bias_and_final_store_indexes() {
    // Pair the tails rather than taking a Cartesian product: each row/group,
    // coefficient-block and column boundary has its own independent oracle.
    for (rows, inner, columns) in [
        (5, 255, 15),
        (6, 256, 16),
        (7, 257, 17),
        (47, 511, 33),
        (48, 512, 17),
        (49, 513, 16),
        (5, 767, 17),
        (6, 768, 16),
        (7, 769, 15),
        (47, 1023, 16),
        (48, 1024, 17),
        (49, 1025, 33),
        (7, 1539, 17),
    ] {
        let mut input = values(rows * inner, 3);
        input[..5].copy_from_slice(&[1e10, -1e10, 3., -0., 0.25]);
        let weights = values(inner * columns, 5);
        let bias = values(columns, 7);
        let packed = PackedMatrix::new(&weights, inner, columns).unwrap();
        for bias in [&[][..], bias.as_slice()] {
            let expected = oracle(Backend::NeonFma, &input, &weights, bias, inner, columns);
            let first = 5;
            for fused in [false, true] {
                let expected: Vec<_> = expected
                    .iter()
                    .enumerate()
                    .map(|(index, &value)| {
                        if fused {
                            ResidualReluStore.scalar(value, first * columns + index)
                        } else {
                            value
                        }
                    })
                    .collect();
                for policy in 0..3 {
                    let mut guarded = vec![f32::from_bits(0x7fc01234); expected.len() + 2];
                    let length = expected.len();
                    let output = &mut guarded[1..length + 1];
                    // SAFETY: this ARM64-only module uses checked complete
                    // buffers and both reductions are fixed positive sizes.
                    unsafe {
                        if fused {
                            call_policy(
                                policy,
                                &input,
                                bias,
                                &packed,
                                output,
                                first,
                                inner,
                                columns,
                                &ResidualReluStore,
                            );
                        } else {
                            call_policy(
                                policy,
                                &input,
                                bias,
                                &packed,
                                output,
                                first,
                                inner,
                                columns,
                                &IdentityStore,
                            );
                        }
                    }
                    assert_bits(
                        output,
                        &expected,
                        &format!("policy={policy} shape={rows}/{inner}/{columns} fused={fused}"),
                    );
                    assert_eq!(guarded[0].to_bits(), 0x7fc01234);
                    assert_eq!(guarded[length + 1].to_bits(), 0x7fc01234);
                }
            }
        }
    }
}

#[target_feature(enable = "neon")]
#[allow(clippy::too_many_arguments)]
unsafe fn call_policy(
    policy: usize,
    input: &[f32],
    bias: &[f32],
    packed: &PackedMatrix,
    output: &mut [f32],
    first: usize,
    inner: usize,
    columns: usize,
    store: &impl StoreTransform,
) {
    // SAFETY: this helper forwards identical checked spans and NEON context.
    unsafe {
        match policy {
            0 => execute(input, bias, packed, output, first, inner, columns, store),
            1 => execute_blocked::<256>(input, bias, packed, output, first, inner, columns, store),
            2 => execute_blocked::<512>(input, bias, packed, output, first, inner, columns, store),
            _ => unreachable!(),
        }
    }
}

#[test]
#[ignore = "local ARM64 release diagnostic: three shapes, one warm-up and three calls per policy; external timeout 10s"]
#[allow(clippy::assertions_on_constants)]
fn arm64_pointwise_k_block_fixed_diagnostic() {
    assert!(
        !cfg!(debug_assertions),
        "run this diagnostic in release mode"
    );
    let started = Instant::now();
    let check_budget = || {
        assert!(
            started.elapsed() < Duration::from_secs(10),
            "fixed K-block diagnostic exceeded ten seconds"
        );
    };
    for (rows, inner, columns) in [(96, 768, 384), (960, 1024, 512), (480, 1536, 768)] {
        let input = values(rows * inner, 3);
        let weights = values(inner * columns, 5);
        let bias = values(columns, 7);
        let packed = PackedMatrix::new(&weights, inner, columns).unwrap();
        let mut outputs = [
            vec![0.; rows * columns],
            vec![0.; rows * columns],
            vec![0.; rows * columns],
        ];
        for (policy, output) in outputs.iter_mut().enumerate() {
            check_budget();
            // SAFETY: all matrices are complete and this module is ARM64-only.
            unsafe {
                call_policy(
                    policy,
                    &input,
                    &bias,
                    &packed,
                    output,
                    0,
                    inner,
                    columns,
                    &IdentityStore,
                )
            };
        }
        assert_bits(&outputs[1], &outputs[0], "K256 warm-up");
        assert_bits(&outputs[2], &outputs[0], "K512 warm-up");
        let mut samples_ms = [[0.; 3]; 3];
        for (sample, timings) in samples_ms.iter_mut().enumerate() {
            // Fixed rotated order bounds position effects without retrying.
            for policy in [[0, 1, 2], [2, 0, 1], [1, 2, 0]][sample] {
                check_budget();
                let timer = Instant::now();
                // SAFETY: identical matrices and buffers from the checked warm-up.
                unsafe {
                    call_policy(
                        policy,
                        &input,
                        &bias,
                        &packed,
                        std::hint::black_box(&mut outputs[policy]),
                        0,
                        inner,
                        columns,
                        &IdentityStore,
                    )
                };
                timings[policy] = timer.elapsed().as_secs_f64() * 1000.;
                check_budget();
                assert_bits(&outputs[policy], &outputs[0], "measured K-block parity");
            }
        }
        println!(
            "{}",
            serde_json::json!({
                "diagnostic": "arm64_pointwise_k_block_fixed", "rows": rows, "inner": inner,
                "columns": columns, "threads": 1, "warmups_per_policy": 1,
                "calls_per_sample": 1, "order": "ABC,CAB,BCA", "samples_by_policy_ms": {
                    "full_k": samples_ms.map(|sample| sample[0]),
                    "k256": samples_ms.map(|sample| sample[1]),
                    "k512": samples_ms.map(|sample| sample[2]),
                }, "exact_output_bits": true, "budget_seconds": 10,
            })
        );
    }
    check_budget();
}

